rity","dataType":2,"isRequired":false},{"width":165,"header":"Comments","binding":"comments","dataType":1},{"width":130,"header":"Date Complete","binding":"dateComplete","dataType":4,"format":"d","isReadOnly":true,"isRequired":false,"cssClass":"read-only"},{"width":140,"header":"PPO","binding":"productionPlanning.productionPlanning","dataType":3,"isRequired":false},{"width":130,"header":"PPO Notes","binding":"productionPlanning.productionPlanningNotes","dataType":1},{"width":130,"header":"Action Items","binding":"productionPlanning.actionItems","dataType":1},{"header":"id","binding":"id","dataType":2,"visible":false,"isReadOnly":true,"isRequired":false},{"header":"ParentLineItemId","binding":"parentLineItem.id","dataType":2,"visible":false,"isReadOnly":true,"isRequired":false},{"header":"Parent Line Item Version","binding":"parentLineItem.version","dataType":2,"visible":false,"isReadOnly":true,"isRequired":false},{"header":"Parent Line Item Work Authorization","binding":"parentLineItem.workAuthorizationNumber","dataType":1,"visible":false,"isReadOnly":true,"isRequired":false},{"header":"Line Item Number","binding":"parentLineItem.lineItemNumber","dataType":1,"visible":false,"isReadOnly":true,"isRequired":false},{"header":"Order Quantity","binding":"parentLineItem.quantity","dataType":2,"visible":false,"isReadOnly":true,"isRequired":false}]}'
